      `TOTALS sheet=${sheet} by=uma claimed-total=100.00 due-total=10.00 overdue-total=9.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=50.00 date=2026-01-08 number=5`,
